select schemaname, tablename from pg_tables where schemaname in ('public','storage') and not rowsecurity;
select schemaname, tablename, policyname, cmd, roles, qual, with_check from pg_policies where 'anon' = any(roles) or 'public' = any(roles) order by 1, 2;
select schemaname, tablename, policyname, cmd from pg_policies where cmd in ('INSERT','UPDATE','DELETE','ALL') and (coalesce(with_check,'') = 'true' or coalesce(qual,'') = 'true');
select n.nspname, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prosecdef and not exists (select 1 from unnest(coalesce(p.proconfig, '{}')) c where c like 'search_path=%');
select n.nspname, p.proname, r.rolname from pg_proc p join pg_namespace n on n.oid = p.pronamespace cross join pg_roles r where n.nspname = 'public' and p.prosecdef and r.rolname = 'anon' and has_function_privilege(r.rolname, p.oid, 'execute');
select grantee, table_name, privilege_type from information_schema.role_table_grants where table_schema = 'public' and grantee = 'anon' and privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE');
select id, public, file_size_limit, allowed_mime_types from storage.buckets where file_size_limit is null or allowed_mime_types is null;
select n.nspname, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname like 'admin\_%' and p.prosrc !~* '(is_adm\s*\(|is_admin|has_perm\s*\()';
select n.nspname, p.proname, p.prosecdef from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname like 'admin\_%' and not p.prosecdef;
select p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname like 'admin\_%' and has_function_privilege('anon', p.oid, 'execute');
select t.relname from (values ('posts'), ('threads'), ('dms'), ('reactions'), ('reports'), ('profile_comments'), ('likes'), ('helpful'), ('board_subs'), ('dm_pins'), ('polls'), ('poll_votes'), ('post_edits')) t(relname) where not exists (select 1 from pg_trigger g join pg_class c on c.oid = g.tgrelid join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname = t.relname and g.tgname = 'zz_rl_' || t.relname and not g.tgisinternal);
select relname, relrowsecurity from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname = 'rl_log' and (not c.relrowsecurity or has_table_privilege('anon', c.oid, 'select') or has_table_privilege('authenticated', c.oid, 'select'));
select grantee, table_name, privilege_type from information_schema.role_table_grants where table_schema = 'public' and grantee in ('anon', 'authenticated') and privilege_type in ('TRUNCATE', 'REFERENCES', 'TRIGGER');
select grantee, table_name, privilege_type from information_schema.role_table_grants where table_schema = 'public' and grantee = 'anon' and privilege_type <> 'SELECT';
